INSERT INTO "product" ("id", "producer_id", "status", "name", "country_of_production", "floor_area_m2", "built_up_area_m2", "description", "completion_standard", "production_lead_time_weeks_min", "production_lead_time_weeks_max", "on_site_assembly_days_min", "on_site_assembly_days_max", "house_price_min_cents", "house_price_max_cents", "structural_warranty_years", "category", "rooms", "bedrooms", "bathrooms", "storeys", "external_dimensions", "roof_type", "construction_system", "foundation_options", "customization_scope", "currency", "price_includes", "price_excludes", "featured", "created_at", "updated_at", "deleted_at", "family", "spa_subcategory", "technical_specs", "cover_image_url", "container_subcategory", "installation_warranty_years", "service_scope_description", "transport_dimensions", "crane_requirements", "min_plot_width_m", "room_layout", "faq", "simplified_permit_eligible", "client_requirements", "video_url", "slug") VALUES ('c20bdb1b-860b-5740-8882-d37c49fe5f3d', 'ee7266d7-bf04-522e-82c3-67e925060fa5', 'published', 'Logbar Monako 67 B', 'PL', 48.84, 52.36, 'Nowoczesny dom o powierzchni zabudowy 52,36 m² (9,69 × 5,62 m) z dużymi przeszkleniami i antresolą z sypialnią. Parter ok. 42 m² z salonem z aneksem kuchennym, pokojem i łazienką oraz antresola 6,76 m² powierzchni użytkowej (24,82 m² po podłodze). Dwuspadowy dach pod kątem 40°. Elewacja B: panel na rąbek w kolorze antracytowym wraz z deską elewacyjną. Taras niezadaszony o powierzchni 34,69 m² jest dostępny jako opcja.', 'deweloperski', NULL, NULL, NULL, NULL, NULL, NULL, 10, 'caloroczny', 3, 2, 1, 1, '9,69 × 5,62 m', 'Dwuspadowy, nachylenie 40°, wysokość do kalenicy 5,74 m; pokrycie: panel na rąbek stojący lub blachodachówka', 'Szkielet drewniany z drewna konstrukcyjnego klasy C24 (słupy 45 × 145 mm), ściany ocieplone wełną mineralną 150 + 50 mm, dach 200 + 50 mm', 'W cenie stopy fundamentowe (podłoga na fundamencie punktowym, U = 0,184 W/(m²·K)). Opcjonalnie płyta fundamentowa w pełni izolowana (U = 0,180 W/(m²·K)) lub płyta przy posadzce betonowej po stronie inwestora.', 'Dopłaty za taras niezadaszony, deskę palona metodą Shou Sugi Ban, gruntowanie i malowanie elewacji, schody zabiegowe, płytę fundamentową w pełni izolowaną, dachówkę ceramiczną i rekuperację. Dopłata do ram okiennych w innym kolorze.', 'EUR', NULL, NULL, false, '2026-10-09T06:28:13.222Z'::timestamptz, '2026-10-09T07:04:41.303Z'::timestamptz, NULL, 'dom', NULL, '{"heatSource":"inne","insulation":"Wełna mineralna: ściany 150 + 50 mm, dach 200 + 50 mm (Uc = 0,148 W/(m²·K)), strop 150 mm, podłoga 150 mm; płyta fundamentowa z EPS grafitowym 50 mm i XPS 100 mm (Uc = 0,180 W/(m²·K)) lub podłoga na stopach (Uc = 0,184 W/(m²·K)).","ventilation":"grawitacyjna","wallBuildUp":"Deska elewacyjna 20 mm na wentylowanej szczelinie (łaty 25 × 40 mm), membrana wiatroizolacyjna, płyta MFP 12 mm, wełna mineralna 150 mm λ = 0,033 W/(mK), konstrukcja słupowa C24 45 × 145 mm, membrana paroszczelna, wełna mineralna 50 mm w ruszcie instalacyjnym 40 × 60 mm, wykończenie deską boazeryjną lub płytą G-K Riduro. Współczynnik przenikania ciepła ściany Uc = 0,195 W/(m²·K).","windowClass":"Stolarka okienna trzyszybowa w kolorze grafitowym; stalowe drzwi zewnętrzne w kolorze grafitowym.","heatSourceOther":"Źródło ciepła nie jest określone w ofercie producenta.","constructionTechnology":"szkielet-drewniany","heatTransferCoefficients":"nieznana"}'::jsonb, NULL, NULL, 2, 'Zakres prac obejmuje montaż domu, montaż stóp fundamentowych, wykonanie izolacji termicznej ścian zewnętrznych, podłogi i dachu, położenie paneli dachowych na rąbek lub blachodachówki, orynnowanie, montaż stolarki okiennej i drzwi zewnętrznych, rozprowadzenie instalacji elektrycznej i wodno-kanalizacyjnej oraz wykonanie elewacji.', NULL, NULL, NULL, '[{"id":"monako-67-b-room-1","name":"Korytarz","areaM2":5.42,"floorLevel":"parter"},{"id":"monako-67-b-room-2","name":"Pokój","areaM2":8.32,"floorLevel":"parter"},{"id":"monako-67-b-room-3","name":"Łazienka","areaM2":4.72,"floorLevel":"parter"},{"id":"monako-67-b-room-4","name":"Salon z aneksem kuchennym","areaM2":23.49,"floorLevel":"parter"},{"id":"monako-67-b-room-5","name":"Antresola","areaM2":6.76,"floorLevel":"poddasze"}]'::jsonb, '[{"id":"monako-67-b-faq-1","answer":"Nie. Do ceny należy doliczyć koszt transportu oraz dźwigu do miejsca montażu. W cenę nie jest wliczony projekt architektoniczno-budowlany.","question":"Czy cena zawiera transport, dźwig i projekt budowlany?"},{"id":"monako-67-b-faq-2","answer":"Tak, wszystkie ceny z oferty producenta są cenami netto. Stawka VAT zależy od przeznaczenia budynku.","question":"Czy podane ceny są cenami netto?"},{"id":"monako-67-b-faq-3","answer":"Producent udziela gwarancji na 24 miesiące na całość domu oraz na 10 lat na konstrukcję.","question":"Jaka jest gwarancja?"},{"id":"monako-67-b-faq-4","answer":"W standardzie z wykończeniem wnętrz ściany i strop są wykończone deską boazeryjną lub płytą G-K, a podłoga ma suchy jastrych, więc nie trzeba ich wykańczać. W stanie surowym zamkniętym (SSZ) tych prac nie ma w cenie.","question":"Czy po montażu trzeba wykańczać wnętrza?"},{"id":"monako-67-b-faq-5","answer":"Tak, za dopłatą. Producent podaje jej wysokość w indywidualnej wycenie.","question":"Czy ramy okienne mogą mieć inny kolor?"},{"id":"monako-67-b-faq-6","answer":"Zakres prac obejmuje montaż domu, montaż stóp fundamentowych, wykonanie izolacji termicznej ścian zewnętrznych, podłogi i dachu, położenie paneli dachowych na rąbek lub blachodachówki, orynnowanie, montaż stolarki okiennej i drzwi zewnętrznych, rozprowadzenie instalacji elektrycznej i wodno-kanalizacyjnej oraz wykonanie elewacji.","question":"Co obejmuje zakres prac producenta?"}]'::jsonb, NULL, '[{"id":"monako-67-b-req-1","key":"dojazd-dla-transportu","label":"Dojazd dla transportu","custom":false},{"id":"monako-67-b-req-2","key":"miejsce-dla-dzwigu","label":"Miejsce dla dźwigu","custom":false},{"id":"monako-67-b-req-3","key":"formalnosci","label":"Formalności","custom":false}]'::jsonb, NULL, 'logbar-monako-67-b') ON CONFLICT DO NOTHING;
