INSERT INTO "product" ("id", "producer_id", "status", "name", "country_of_production", "floor_area_m2", "built_up_area_m2", "description", "completion_standard", "production_lead_time_weeks_min", "production_lead_time_weeks_max", "on_site_assembly_days_min", "on_site_assembly_days_max", "house_price_min_cents", "house_price_max_cents", "structural_warranty_years", "category", "rooms", "bedrooms", "bathrooms", "storeys", "external_dimensions", "roof_type", "construction_system", "foundation_options", "customization_scope", "currency", "price_includes", "price_excludes", "featured", "created_at", "updated_at", "deleted_at", "family", "spa_subcategory", "technical_specs", "cover_image_url", "container_subcategory", "installation_warranty_years", "service_scope_description", "transport_dimensions", "crane_requirements", "min_plot_width_m", "room_layout", "faq", "simplified_permit_eligible", "client_requirements", "video_url", "slug") VALUES ('2f3ae25e-f627-5fec-b971-1db7901f05df', 'ee7266d7-bf04-522e-82c3-67e925060fa5', 'published', 'Logbar Viking', 'PL', 101.72, 109.98, 'Parterowy dom z antresolą o powierzchni zabudowy 109,98 m² (14,1 × 7,8 m), z konstrukcją w całości z drewna konstrukcyjnego. Pokój, sypialnia, duża przestrzeń kuchni, salonu i jadalni (36,39 m²), dwie łazienki, pomieszczenie gospodarcze i antresola, razem ok. 102 m² powierzchni użytkowej (131 m² po podłodze). Dwuspadowy dach pod kątem 40° i wysoko przeszklony szczyt. Do wyboru stan surowy zamknięty lub stan deweloperski, taras o powierzchni 57,28 m² jako opcja.', 'deweloperski', NULL, NULL, NULL, NULL, NULL, NULL, 10, 'caloroczny', 4, 3, 2, 1, '14,1 × 7,8 m', 'Dwuspadowy, nachylenie 40°, wysokość do kalenicy 6,28 m; pokrycie: blachodachówka', 'Szkielet drewniany z drewna konstrukcyjnego KVH / klasy C24 (45 × 145 mm), ściany ocieplone wełną 150 + 50 mm, dach 200 + 50 mm', 'Płyta fundamentowa zbrojona 200 mm, izolowana poziomo i pionowo XPS 100 mm, z instalacjami, na piasku zagęszczonym warstwami 300–400 mm, w cenie. Dopłata za podłogę z suchym jastrychem w stanie deweloperskim jest już uwzględniona w cenie tego standardu.', 'Dopłaty za modyfikację seryjnego projektu produkcyjnego, drzwi pasywne, przesuwne okno tarasowe, deskę palona metodą Shou Sugi Ban, gruntowanie i malowanie deski elewacyjnej, taras, schody zabiegowe oraz dodatkowe przyłącza zewnętrzne. Przewody pod oświetlenie zewnętrzne, kamery i alarm wyceniane indywidualnie.', 'EUR', NULL, NULL, false, '2026-10-09T06:28:16.755Z'::timestamptz, '2026-10-09T07:04:44.165Z'::timestamptz, NULL, 'dom', NULL, '{"heatSource":"inne","insulation":"Wełna izolacyjna: ściany 150 + 50 mm, dach 200 + 50 mm, strop 150 mm; płyta fundamentowa z XPS 100 mm.","ventilation":"grawitacyjna","wallBuildUp":"Deska elewacyjna, łaty 40 × 30 mm i szczelina wentylacyjna, blacha perforowana, wiatroizolacja, płyta MFP 12 mm, konstrukcja drewniana C24 45 × 145 mm, wełna 150 mm λ = 0,033 W/(mK), paroizolacja, ruszt instalacyjny 60 × 40 mm z wełną 50 mm, płyta gipsowo-kartonowa Riduro.","windowClass":"Stolarka okienna trzyszybowa sześciokomorowa, antracytowa od zewnątrz i biała od wewnątrz; drzwi Gerda lub Wikęd.","heatSourceOther":"Źródło ciepła nie jest określone w ofercie producenta.","constructionTechnology":"szkielet-drewniany","heatTransferCoefficients":"nieznana"}'::jsonb, NULL, NULL, 2, 'Cena obejmuje płytę fundamentową izolowaną poziomo i pionowo płytami XPS, zbrojoną, z instalacjami, w pełni wykończony dom z zewnątrz, instalacje elektryczne i wodno-kanalizacyjne oraz zadaszenie wejścia.', NULL, NULL, NULL, '[{"id":"viking-room-1","name":"Wiatrołap","areaM2":4.11,"floorLevel":"parter"},{"id":"viking-room-2","name":"Pokój","areaM2":10.97,"floorLevel":"parter"},{"id":"viking-room-3","name":"Sypialnia","areaM2":13.78,"floorLevel":"parter"},{"id":"viking-room-4","name":"Łazienka","areaM2":8.2,"floorLevel":"parter"},{"id":"viking-room-5","name":"Pomieszczenie gospodarcze","areaM2":2.31,"floorLevel":"parter"},{"id":"viking-room-6","name":"Korytarz","areaM2":6.59,"floorLevel":"parter"},{"id":"viking-room-7","name":"Kuchnia, salon, jadalnia","areaM2":36.39,"floorLevel":"parter"},{"id":"viking-room-8","name":"Przestrzeń antresoli","areaM2":17.47,"floorLevel":"poddasze"},{"id":"viking-room-9","name":"Łazienka","areaM2":1.9,"floorLevel":"poddasze"}]'::jsonb, '[{"id":"viking-faq-1","answer":"Nie. Do ceny należy doliczyć koszt transportu oraz dźwigu do miejsca montażu. W cenę nie jest wliczony projekt architektoniczno-budowlany.","question":"Czy cena zawiera transport, dźwig i projekt budowlany?"},{"id":"viking-faq-2","answer":"Tak, wszystkie ceny z oferty producenta są cenami netto. Stawka VAT zależy od przeznaczenia budynku.","question":"Czy podane ceny są cenami netto?"},{"id":"viking-faq-3","answer":"Producent udziela gwarancji na 24 miesiące na całość domu oraz na 10 lat na konstrukcję.","question":"Jaka jest gwarancja?"},{"id":"viking-faq-4","answer":"W stanie deweloperskim podłoga ma suchy jastrych, a ściany i sufity są wykończone płytą G-K Riduro (bez szpachlowania). W stanie surowym zamkniętym wnętrza wykańcza inwestor.","question":"Czy po montażu trzeba wykańczać wnętrza?"},{"id":"viking-faq-5","answer":"Cena obejmuje płytę fundamentową izolowaną poziomo i pionowo płytami XPS, zbrojoną, z instalacjami, w pełni wykończony dom z zewnątrz, instalacje elektryczne i wodno-kanalizacyjne oraz zadaszenie wejścia.","question":"Co obejmuje zakres prac producenta?"}]'::jsonb, NULL, '[{"id":"viking-req-1","key":"dojazd-dla-transportu","label":"Dojazd dla transportu","custom":false},{"id":"viking-req-2","key":"miejsce-dla-dzwigu","label":"Miejsce dla dźwigu","custom":false},{"id":"viking-req-3","key":"formalnosci","label":"Formalności","custom":false}]'::jsonb, NULL, 'logbar-viking') ON CONFLICT DO NOTHING;
INSERT INTO "product" ("id", "producer_id", "status", "name", "country_of_production", "floor_area_m2", "built_up_area_m2", "description", "completion_standard", "production_lead_time_weeks_min", "production_lead_time_weeks_max", "on_site_assembly_days_min", "on_site_assembly_days_max", "house_price_min_cents", "house_price_max_cents", "structural_warranty_years", "category", "rooms", "bedrooms", "bathrooms", "storeys", "external_dimensions", "roof_type", "construction_system", "foundation_options", "customization_scope", "currency", "price_includes", "price_excludes", "featured", "created_at", "updated_at", "deleted_at", "family", "spa_subcategory", "technical_specs", "cover_image_url", "container_subcategory", "installation_warranty_years", "service_scope_description", "transport_dimensions", "crane_requirements", "min_plot_width_m", "room_layout", "faq", "simplified_permit_eligible", "client_requirements", "video_url", "slug") VALUES ('6eda9117-7834-587b-9e78-7ebaecbf07c4', 'ee7266d7-bf04-522e-82c3-67e925060fa5', 'published', 'Logbar Monako 67 A', 'PL', 48.84, 52.36, 'Nowoczesny dom o powierzchni zabudowy 52,36 m² (9,69 × 5,62 m) z dużymi przeszkleniami i antresolą z sypialnią. Parter ok. 42 m² z salonem z aneksem kuchennym, pokojem i łazienką oraz antresola 6,76 m² powierzchni użytkowej (24,82 m² po podłodze). Dwuspadowy dach pod kątem 40°. Elewacja A: jasna deska elewacyjna profilowana z elementami z drewna opalanego Shou Sugi Ban. Taras niezadaszony o powierzchni 34,69 m² jest dostępny jako opcja.', 'deweloperski', NULL, NULL, NULL, NULL, NULL, NULL, 10, 'caloroczny', 3, 2, 1, 1, '9,69 × 5,62 m', 'Dwuspadowy, nachylenie 40°, wysokość do kalenicy 5,74 m; pokrycie: panel na rąbek stojący lub blachodachówka', 'Szkielet drewniany z drewna konstrukcyjnego klasy C24 (słupy 45 × 145 mm), ściany ocieplone wełną mineralną 150 + 50 mm, dach 200 + 50 mm', 'W cenie stopy fundamentowe (podłoga na fundamencie punktowym, U = 0,184 W/(m²·K)). Opcjonalnie płyta fundamentowa w pełni izolowana (U = 0,180 W/(m²·K)) lub płyta przy posadzce betonowej po stronie inwestora.', 'Dopłaty za taras niezadaszony, deskę palona metodą Shou Sugi Ban, gruntowanie i malowanie elewacji, schody zabiegowe, płytę fundamentową w pełni izolowaną, dachówkę ceramiczną i rekuperację. Dopłata do ram okiennych w innym kolorze.', 'EUR', NULL, NULL, false, '2026-10-09T06:28:12.930Z'::timestamptz, '2026-10-09T07:04:41.048Z'::timestamptz, NULL, 'dom', NULL, '{"heatSource":"inne","insulation":"Wełna mineralna: ściany 150 + 50 mm, dach 200 + 50 mm (Uc = 0,148 W/(m²·K)), strop 150 mm, podłoga 150 mm; płyta fundamentowa z EPS grafitowym 50 mm i XPS 100 mm (Uc = 0,180 W/(m²·K)) lub podłoga na stopach (Uc = 0,184 W/(m²·K)).","ventilation":"grawitacyjna","wallBuildUp":"Deska elewacyjna 20 mm na wentylowanej szczelinie (łaty 25 × 40 mm), membrana wiatroizolacyjna, płyta MFP 12 mm, wełna mineralna 150 mm λ = 0,033 W/(mK), konstrukcja słupowa C24 45 × 145 mm, membrana paroszczelna, wełna mineralna 50 mm w ruszcie instalacyjnym 40 × 60 mm, wykończenie deską boazeryjną lub płytą G-K Riduro. Współczynnik przenikania ciepła ściany Uc = 0,195 W/(m²·K).","windowClass":"Stolarka okienna trzyszybowa w kolorze grafitowym; stalowe drzwi zewnętrzne w kolorze grafitowym.","heatSourceOther":"Źródło ciepła nie jest określone w ofercie producenta.","constructionTechnology":"szkielet-drewniany","heatTransferCoefficients":"nieznana"}'::jsonb, NULL, NULL, 2, 'Zakres prac obejmuje montaż domu, montaż stóp fundamentowych, wykonanie izolacji termicznej ścian zewnętrznych, podłogi i dachu, położenie paneli dachowych na rąbek lub blachodachówki, orynnowanie, montaż stolarki okiennej i drzwi zewnętrznych, rozprowadzenie instalacji elektrycznej i wodno-kanalizacyjnej oraz wykonanie elewacji.', NULL, NULL, NULL, '[{"id":"monako-67-a-room-1","name":"Korytarz","areaM2":5.42,"floorLevel":"parter"},{"id":"monako-67-a-room-2","name":"Pokój","areaM2":8.32,"floorLevel":"parter"},{"id":"monako-67-a-room-3","name":"Łazienka","areaM2":4.72,"floorLevel":"parter"},{"id":"monako-67-a-room-4","name":"Salon z aneksem kuchennym","areaM2":23.49,"floorLevel":"parter"},{"id":"monako-67-a-room-5","name":"Antresola","areaM2":6.76,"floorLevel":"poddasze"}]'::jsonb, '[{"id":"monako-67-a-faq-1","answer":"Nie. Do ceny należy doliczyć koszt transportu oraz dźwigu do miejsca montażu. W cenę nie jest wliczony projekt architektoniczno-budowlany.","question":"Czy cena zawiera transport, dźwig i projekt budowlany?"},{"id":"monako-67-a-faq-2","answer":"Tak, wszystkie ceny z oferty producenta są cenami netto. Stawka VAT zależy od przeznaczenia budynku.","question":"Czy podane ceny są cenami netto?"},{"id":"monako-67-a-faq-3","answer":"Producent udziela gwarancji na 24 miesiące na całość domu oraz na 10 lat na konstrukcję.","question":"Jaka jest gwarancja?"},{"id":"monako-67-a-faq-4","answer":"W standardzie z wykończeniem wnętrz ściany i strop są wykończone deską boazeryjną lub płytą G-K, a podłoga ma suchy jastrych, więc nie trzeba ich wykańczać. W stanie surowym zamkniętym (SSZ) tych prac nie ma w cenie.","question":"Czy po montażu trzeba wykańczać wnętrza?"},{"id":"monako-67-a-faq-5","answer":"Tak, za dopłatą. Producent podaje jej wysokość w indywidualnej wycenie.","question":"Czy ramy okienne mogą mieć inny kolor?"},{"id":"monako-67-a-faq-6","answer":"Zakres prac obejmuje montaż domu, montaż stóp fundamentowych, wykonanie izolacji termicznej ścian zewnętrznych, podłogi i dachu, położenie paneli dachowych na rąbek lub blachodachówki, orynnowanie, montaż stolarki okiennej i drzwi zewnętrznych, rozprowadzenie instalacji elektrycznej i wodno-kanalizacyjnej oraz wykonanie elewacji.","question":"Co obejmuje zakres prac producenta?"}]'::jsonb, NULL, '[{"id":"monako-67-a-req-1","key":"dojazd-dla-transportu","label":"Dojazd dla transportu","custom":false},{"id":"monako-67-a-req-2","key":"miejsce-dla-dzwigu","label":"Miejsce dla dźwigu","custom":false},{"id":"monako-67-a-req-3","key":"formalnosci","label":"Formalności","custom":false}]'::jsonb, NULL, 'logbar-monako-67-a') ON CONFLICT DO NOTHING;
