INSERT INTO "product" ("id", "producer_id", "status", "name", "country_of_production", "floor_area_m2", "built_up_area_m2", "description", "completion_standard", "production_lead_time_weeks_min", "production_lead_time_weeks_max", "on_site_assembly_days_min", "on_site_assembly_days_max", "house_price_min_cents", "house_price_max_cents", "structural_warranty_years", "category", "rooms", "bedrooms", "bathrooms", "storeys", "external_dimensions", "roof_type", "construction_system", "foundation_options", "customization_scope", "currency", "price_includes", "price_excludes", "featured", "created_at", "updated_at", "deleted_at", "family", "spa_subcategory", "technical_specs", "cover_image_url", "container_subcategory", "installation_warranty_years", "service_scope_description", "transport_dimensions", "crane_requirements", "min_plot_width_m", "room_layout", "faq", "simplified_permit_eligible", "client_requirements", "video_url", "slug") VALUES ('d7a203c9-e394-5dac-802d-1de2176c89b8', 'ee7266d7-bf04-522e-82c3-67e925060fa5', 'published', 'Logbar Monako 111 B', 'PL', 87.75, 82.89, 'Nowoczesny dom o powierzchni zabudowy 82,89 m² (11,68 × 7,1 m) z dużymi przeszkleniami w szczycie. Parter 55,38 m² z salonem z aneksem kuchennym, dwoma pokojami i łazienką oraz piętro 32,37 m² z dwoma pokojami i łazienką, razem ok. 88 m² powierzchni użytkowej (111 m² po podłodze). Dwuspadowy dach pod kątem 40°, taras zadaszony 12,63 m² w bryle domu. Elewacja B: deska elewacyjna opalana metodą Shou Sugi Ban z elementami z jasnej deski świerkowej, płaskiej. Taras niezadaszony 38,90 m² jest dostępny jako opcja.', 'deweloperski', NULL, NULL, NULL, NULL, NULL, NULL, 10, 'caloroczny', 5, 4, 2, 2, '11,68 × 7,1 m', 'Dwuspadowy, nachylenie 40°, wysokość do kalenicy 6,72 m; pokrycie: panel na rąbek stojący lub blachodachówka', 'Szkielet drewniany z drewna konstrukcyjnego klasy C24 (słupy 45 × 145 mm), ściany ocieplone wełną mineralną 150 + 50 mm, dach 200 + 50 mm', 'W cenie stopy fundamentowe (podłoga na fundamencie punktowym, U = 0,184 W/(m²·K)). Opcjonalnie płyta fundamentowa w pełni izolowana (U = 0,180 W/(m²·K)) lub płyta przy posadzce betonowej po stronie inwestora.', 'Dopłaty za taras niezadaszony, gruntowanie i malowanie elewacji, schody zabiegowe oraz płytę fundamentową w pełni izolowaną ze stopami pod wykuszem. Dopłata do ram okiennych w innym kolorze.', 'EUR', NULL, NULL, false, '2026-10-09T06:28:14.354Z'::timestamptz, '2026-10-09T07:04:42.301Z'::timestamptz, NULL, 'dom', NULL, '{"heatSource":"inne","insulation":"Wełna mineralna: ściany 150 + 50 mm, dach 200 + 50 mm (Uc = 0,148 W/(m²·K)), strop 150 mm, podłoga 150 mm; płyta fundamentowa z EPS grafitowym 50 mm i XPS 100 mm (Uc = 0,180 W/(m²·K)) lub podłoga na stopach (Uc = 0,184 W/(m²·K)).","ventilation":"grawitacyjna","wallBuildUp":"Deska elewacyjna 20 mm na wentylowanej szczelinie (łaty 25 × 40 mm), membrana wiatroizolacyjna, płyta MFP 12 mm, wełna mineralna 150 mm λ = 0,033 W/(mK), konstrukcja słupowa C24 45 × 145 mm, membrana paroszczelna, wełna mineralna 50 mm w ruszcie instalacyjnym 40 × 60 mm, wykończenie deską boazeryjną lub płytą G-K Riduro. Współczynnik przenikania ciepła ściany Uc = 0,195 W/(m²·K).","windowClass":"Stolarka okienna trzyszybowa w kolorze grafitowym; stalowe drzwi zewnętrzne w kolorze grafitowym.","heatSourceOther":"Źródło ciepła nie jest określone w ofercie producenta.","constructionTechnology":"szkielet-drewniany","heatTransferCoefficients":"nieznana"}'::jsonb, NULL, NULL, 2, 'Zakres prac obejmuje montaż domu, montaż stóp fundamentowych, wykonanie izolacji termicznej ścian zewnętrznych, podłogi i dachu, położenie paneli dachowych na rąbek lub blachodachówki, orynnowanie, montaż stolarki okiennej i drzwi zewnętrznych, rozprowadzenie instalacji elektrycznej i wodno-kanalizacyjnej oraz wykonanie elewacji.', NULL, NULL, NULL, '[{"id":"monako-111-b-room-1","name":"Korytarz","areaM2":7.86,"floorLevel":"parter"},{"id":"monako-111-b-room-2","name":"Pokój","areaM2":8.55,"floorLevel":"parter"},{"id":"monako-111-b-room-3","name":"Pokój","areaM2":8.59,"floorLevel":"parter"},{"id":"monako-111-b-room-4","name":"Łazienka","areaM2":5.12,"floorLevel":"parter"},{"id":"monako-111-b-room-5","name":"Salon z aneksem kuchennym","areaM2":25.26,"floorLevel":"parter"},{"id":"monako-111-b-room-6","name":"Korytarz","areaM2":3.17,"floorLevel":"pietro"},{"id":"monako-111-b-room-7","name":"Pokój","areaM2":14.41,"floorLevel":"pietro"},{"id":"monako-111-b-room-8","name":"Łazienka","areaM2":1.05,"floorLevel":"pietro"},{"id":"monako-111-b-room-9","name":"Pokój","areaM2":13.73,"floorLevel":"pietro"}]'::jsonb, '[{"id":"monako-111-b-faq-1","answer":"Nie. Do ceny należy doliczyć koszt transportu oraz dźwigu do miejsca montażu. W cenę nie jest wliczony projekt architektoniczno-budowlany.","question":"Czy cena zawiera transport, dźwig i projekt budowlany?"},{"id":"monako-111-b-faq-2","answer":"Tak, wszystkie ceny z oferty producenta są cenami netto. Stawka VAT zależy od przeznaczenia budynku.","question":"Czy podane ceny są cenami netto?"},{"id":"monako-111-b-faq-3","answer":"Producent udziela gwarancji na 24 miesiące na całość domu oraz na 10 lat na konstrukcję.","question":"Jaka jest gwarancja?"},{"id":"monako-111-b-faq-4","answer":"W standardzie z wykończeniem wnętrz ściany i strop są wykończone deską boazeryjną lub płytą G-K, a podłoga ma suchy jastrych, więc nie trzeba ich wykańczać. W stanie surowym zamkniętym (SSZ) tych prac nie ma w cenie.","question":"Czy po montażu trzeba wykańczać wnętrza?"},{"id":"monako-111-b-faq-5","answer":"Tak, za dopłatą. Producent podaje jej wysokość w indywidualnej wycenie.","question":"Czy ramy okienne mogą mieć inny kolor?"},{"id":"monako-111-b-faq-6","answer":"Zakres prac obejmuje montaż domu, montaż stóp fundamentowych, wykonanie izolacji termicznej ścian zewnętrznych, podłogi i dachu, położenie paneli dachowych na rąbek lub blachodachówki, orynnowanie, montaż stolarki okiennej i drzwi zewnętrznych, rozprowadzenie instalacji elektrycznej i wodno-kanalizacyjnej oraz wykonanie elewacji.","question":"Co obejmuje zakres prac producenta?"}]'::jsonb, NULL, '[{"id":"monako-111-b-req-1","key":"dojazd-dla-transportu","label":"Dojazd dla transportu","custom":false},{"id":"monako-111-b-req-2","key":"miejsce-dla-dzwigu","label":"Miejsce dla dźwigu","custom":false},{"id":"monako-111-b-req-3","key":"formalnosci","label":"Formalności","custom":false}]'::jsonb, NULL, 'logbar-monako-111-b') ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('b6152ce9-1459-484e-96dc-d0c3f619a9dc', '6eda9117-7834-587b-9e78-7ebaecbf07c4', 'en', 'Logbar Monako 67 A', 'A modern house with a footprint of 52.36 m² (9.69 × 5.62 m), large glazed areas and a mezzanine bedroom. A ground floor of about 42 m² with a living room with kitchenette, a room and a bathroom, and a mezzanine of 6.76 m² usable floor area (24.82 m² measured at floor level). Gable roof at 40°. Façade A: light profiled cladding boards with elements of Shou Sugi Ban charred wood. An uncovered terrace of 34.69 m² is available as an option.', '2026-10-09T06:28:12.930Z'::timestamptz, '2026-10-09T07:04:51.610Z'::timestamptz, '[{"id":"monako-67-a-room-1","name":"Hallway"},{"id":"monako-67-a-room-2","name":"Room"},{"id":"monako-67-a-room-3","name":"Bathroom"},{"id":"monako-67-a-room-4","name":"Living room with kitchenette"},{"id":"monako-67-a-room-5","name":"Mezzanine"}]'::jsonb, '[{"id":"monako-67-a-faq-1","answer":"No. The cost of transport and of a crane at the assembly site must be added to the price. The architectural and building design is not included.","question":"Does the price include transport, a crane and the building design?"},{"id":"monako-67-a-faq-2","answer":"Yes, all prices in the producer''s offer are net prices. The VAT rate depends on the intended use of the building.","question":"Are the prices net prices?"},{"id":"monako-67-a-faq-3","answer":"The producer gives a 24-month warranty on the whole house and a 10-year warranty on the structure.","question":"What is the warranty?"},{"id":"monako-67-a-faq-4","answer":"In the finished-interior standard the walls and ceiling are finished with tongue-and-groove boards or plasterboard and the floor has a dry screed, so they need no further finishing. In the closed-shell state (SSZ) this work is not included in the price.","question":"Do the interiors need finishing after assembly?"},{"id":"monako-67-a-faq-5","answer":"Yes, for a surcharge. The producer states its amount in an individual quotation.","question":"Can the window frames have a different colour?"},{"id":"monako-67-a-faq-6","answer":"The scope of work includes assembling the house, installing the foundation pads, insulating the external walls, floor and roof, laying standing-seam roof panels or metal roof tiles, guttering, installing the windows and external doors, running the electrical and water and sewage installations, and finishing the façade.","question":"What does the producer''s scope of work cover?"}]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'Foundation pads are included in the price (floor on a point foundation, U = 0.184 W/(m²·K)). A fully insulated foundation slab (U = 0.180 W/(m²·K)) or a slab with a concrete floor provided by the investor is optional.', NULL, 'Timber frame of C24 structural timber (45 × 145 mm studs), walls insulated with 150 + 50 mm mineral wool, roof 200 + 50 mm', 'Gable roof, 40° pitch, ridge height 5.74 m; covering: standing-seam panels or metal roof tiles', 'Surcharges for an uncovered terrace, boards charred with the Shou Sugi Ban method, priming and painting of the façade, winder stairs, a fully insulated foundation slab, ceramic roof tiles and heat recovery ventilation. Surcharge for window frames in a different colour.', 'The scope of work includes assembling the house, installing the foundation pads, insulating the external walls, floor and roof, laying standing-seam roof panels or metal roof tiles, guttering, installing the windows and external doors, running the electrical and water and sewage installations, and finishing the façade.') ON CONFLICT DO NOTHING;
