INSERT INTO "product_variant_translation" ("id", "product_variant_id", "locale", "scope_summary", "created_at", "updated_at", "excluded_scope", "variant_label") VALUES ('528aad37-0dd5-496c-a638-559561a00aaa', 'f7c8f6d6-d9c6-54c5-bb4a-fb73dc25edcb', 'en', 'Closed shell (SSZ): the same scope as the finished-interior standard, but without the dry-screed floor and without finishing the walls and ceilings with tongue-and-groove boards or plasterboard.', '2026-10-09T06:28:13.269Z'::timestamptz, '2026-10-09T07:04:51.930Z'::timestamptz, 'The dry-screed floor, finishing of walls and ceilings with tongue-and-groove boards or plasterboard, transport, a crane at the assembly site and the architectural and building design.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_variant_translation" ("id", "product_variant_id", "locale", "scope_summary", "created_at", "updated_at", "excluded_scope", "variant_label") VALUES ('28c7cccf-957a-4775-8f94-eb93383330a5', 'f7c8f6d6-d9c6-54c5-bb4a-fb73dc25edcb', 'de', 'Rohbau geschlossen (SSZ): Leistungsumfang wie beim Standard mit Innenausbau, jedoch ohne Trockenestrich und ohne Wand- und Deckenverkleidung aus Profilholz oder Gipskartonplatten.', '2026-10-09T06:28:13.269Z'::timestamptz, '2026-10-09T07:04:51.930Z'::timestamptz, 'Trockenestrich, Wand- und Deckenverkleidung aus Profilholz oder Gipskartonplatten, Transport, ein Kran am Montageort und die Architektur- und Bauplanung.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_variant_translation" ("id", "product_variant_id", "locale", "scope_summary", "created_at", "updated_at", "excluded_scope", "variant_label") VALUES ('e0067506-d479-4c2e-aeb5-e14daf140355', 'f7c8f6d6-d9c6-54c5-bb4a-fb73dc25edcb', 'nl', 'Casco dicht (SSZ): hetzelfde pakket als de afbouwstandaard, maar zonder droge dekvloer en zonder afwerking van wanden en plafonds met profielplanken of gipsplaten.', '2026-10-09T06:28:13.269Z'::timestamptz, '2026-10-09T07:04:51.930Z'::timestamptz, 'De droge dekvloer, afwerking van wanden en plafonds met profielplanken of gipsplaten, transport, een kraan op de montagelocatie en het architectonisch en bouwkundig ontwerp.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_variant_translation" ("id", "product_variant_id", "locale", "scope_summary", "created_at", "updated_at", "excluded_scope", "variant_label") VALUES ('56fa844c-4204-48bc-b70d-cea94040b69e', '75ffdd2a-5f6b-549a-95bc-a25b75178a56', 'en', 'Finished-interior standard: the house is fully completed on the outside, with foundation pads, sound-deadening of the ceiling, a floor covered with dry screed, walls and ceiling finished with tongue-and-groove boards or plasterboard, temporary stairs, and electrical (35 points) and water and sewage (14 points) installations.', '2026-10-09T06:28:13.269Z'::timestamptz, '2026-10-09T07:04:51.931Z'::timestamptz, 'Transport, a crane at the assembly site and the architectural and building design.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_variant_translation" ("id", "product_variant_id", "locale", "scope_summary", "created_at", "updated_at", "excluded_scope", "variant_label") VALUES ('cd3afbed-2437-4541-a666-391b96a7dc9b', '75ffdd2a-5f6b-549a-95bc-a25b75178a56', 'de', 'Standard mit Innenausbau: Das Haus ist außen komplett fertiggestellt, mit Punktfundamenten, Schalldämmung der Decke, Trockenestrich im Boden, Wänden und Decke aus Profilholz oder Gipskartonplatten, provisorischer Treppe, sowie Elektro- (35 Punkte) und Wasser-/Abwasserinstallation (14 Punkte).', '2026-10-09T06:28:13.269Z'::timestamptz, '2026-10-09T07:04:51.931Z'::timestamptz, 'Transport, ein Kran am Montageort und die Architektur- und Bauplanung.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_variant_translation" ("id", "product_variant_id", "locale", "scope_summary", "created_at", "updated_at", "excluded_scope", "variant_label") VALUES ('c7d815e5-7207-463d-8e34-b8d7f360c2ee', '75ffdd2a-5f6b-549a-95bc-a25b75178a56', 'nl', 'Afbouwstandaard met afgewerkt interieur: het huis is aan de buitenzijde volledig afgewerkt, met funderingspoeren, geluiddemping van het plafond, een vloer met droge dekvloer, wanden en plafond afgewerkt met profielplanken of gipsplaten, een tijdelijke trap, en elektrische (35 punten) en water- en rioolinstallaties (14 punten).', '2026-10-09T06:28:13.269Z'::timestamptz, '2026-10-09T07:04:51.931Z'::timestamptz, 'Transport, een kraan op de montagelocatie en het architectonisch en bouwkundig ontwerp.', NULL) ON CONFLICT DO NOTHING;
